/**
 * Tests for the spawn-free linked-worktree scanner (#3422).
 *
 * Real fs against a temp dir — the module's whole contract is "what git
 * actually wrote on disk", so mocking fs would test the mock. The layout
 * below is exactly what `git worktree add` produces.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdirSync, mkdtempSync, rmSync, utimesSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { listLinkedWorktrees, resolveCommonGitDir } from '../../lib/worktree-scan.js';

let root: string;
let repo: string;

/** Register a linked worktree the way `git worktree add` does. */
function addWorktree(name: string, branch: string | null, atMs?: number): string {
  const wtPath = join(root, name);
  mkdirSync(wtPath, { recursive: true });
  writeFileSync(join(wtPath, '.git'), `gitdir: ${join(repo, '.git', 'worktrees', name)}\n`);

  const priv = join(repo, '.git', 'worktrees', name);
  mkdirSync(priv, { recursive: true });
  writeFileSync(join(priv, 'gitdir'), `${join(wtPath, '.git')}\n`);
  writeFileSync(join(priv, 'HEAD'), branch ? `ref: refs/heads/${branch}\n` : 'a1b2c3d4\n');

  if (atMs !== undefined) {
    const secs = atMs / 1000;
    utimesSync(join(priv, 'HEAD'), secs, secs);
  }
  return wtPath;
}

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), 'wtscan-'));
  repo = join(root, 'repo');
  mkdirSync(join(repo, '.git'), { recursive: true });
  writeFileSync(join(repo, '.git', 'HEAD'), 'ref: refs/heads/main\n');
});

afterEach(() => {
  rmSync(root, { recursive: true, force: true });
});

describe('listLinkedWorktrees', () => {
  it('returns nothing when the repo has no linked worktrees', () => {
    expect(listLinkedWorktrees(repo)).toEqual([]);
  });

  it('returns [] rather than throwing when the path is not a repo', () => {
    expect(listLinkedWorktrees(join(root, 'nope'))).toEqual([]);
  });

  it('reads path and branch for each registered worktree', () => {
    const a = addWorktree('feat-a', 'fix/aaa');
    const b = addWorktree('feat-b', 'feature/bbb');

    const found = listLinkedWorktrees(repo);
    expect(found.map((w) => w.path).sort()).toEqual([a, b].sort());
    expect(found.find((w) => w.path === a)?.branch).toBe('fix/aaa');
    expect(found.find((w) => w.path === b)?.branch).toBe('feature/bbb');
  });

  it("reports a detached worktree's branch as empty, not as a sha", () => {
    addWorktree('detached', null);
    expect(listLinkedWorktrees(repo)[0].branch).toBe('');
  });

  it('orders by most recent activity first', () => {
    const now = Date.now();
    addWorktree('old', 'fix/old', now - 60 * 60 * 1000);
    const recent = addWorktree('recent', 'fix/recent', now);

    expect(listLinkedWorktrees(repo)[0].path).toBe(recent);
  });

  it('skips a stale registration whose checkout is gone', () => {
    const live = addWorktree('live', 'fix/live');
    const dead = addWorktree('dead', 'fix/dead');
    rmSync(dead, { recursive: true, force: true });

    // A `git -C <path>` suggestion pointing at a deleted directory cannot run,
    // so an unpruned registration must never become a rewrite candidate.
    expect(listLinkedWorktrees(repo).map((w) => w.path)).toEqual([live]);
  });

  it('skips an unreadable registration without losing its siblings', () => {
    const good = addWorktree('good', 'fix/good');
    const priv = join(repo, '.git', 'worktrees', 'broken');
    mkdirSync(priv, { recursive: true }); // registered, but no gitdir/HEAD files

    expect(listLinkedWorktrees(repo).map((w) => w.path)).toEqual([good]);
  });

  it('enumerates siblings when called from inside a linked worktree', () => {
    // The deny path may run with project_dir pointing at a worktree rather
    // than the primary tree; the common dir has to resolve either way.
    const a = addWorktree('feat-a', 'fix/aaa');
    addWorktree('feat-b', 'feature/bbb');

    expect(listLinkedWorktrees(a).map((w) => w.path).sort()).toEqual(
      [a, join(root, 'feat-b')].sort(),
    );
  });
});

describe('resolveCommonGitDir', () => {
  it('returns the .git directory of a primary tree', () => {
    expect(resolveCommonGitDir(repo)).toBe(join(repo, '.git'));
  });

  it('walks up from a linked worktree to the common dir', () => {
    const wt = addWorktree('feat-a', 'fix/aaa');
    expect(resolveCommonGitDir(wt)).toBe(join(repo, '.git'));
  });

  it('throws when .git is a malformed pointer file', () => {
    const bad = join(root, 'bad');
    mkdirSync(bad, { recursive: true });
    writeFileSync(join(bad, '.git'), 'not a gitdir pointer\n');
    expect(() => resolveCommonGitDir(bad)).toThrow();
  });
});
